    art_run_ok rn -> rn_tp rn = 0x675a80 -> rn_key rn = 0 -> rn_tsd rn = 0x696f38 -> rn_loff rn = 0x10 ->
    hl_img_hi L <= BIGSHADOW_LO /\ HAJ.asan_iface_okR L (rn_ar rn) C scfg (HIR BUDGET MAPS0 RESV0 NOACC0 BASE rn)
